var STATUS={"vorbereitung": {"de": "In Vorbereitung", "en": "Preparing", "tone": "neutral", "icon": "pen-line"}, "versendet": {"de": "Warte auf Rückmeldung", "en": "Awaiting reply", "tone": "info", "icon": "send"}, "rueckfrage_faellig": {"de": "Rückfrage fällig", "en": "Follow-up due", "tone": "warning", "icon": "bell"}, "rueckfrage_gesendet": {"de": "Rückfrage gesendet", "en": "Follow-up sent", "tone": "info", "icon": "message-square"}, "telefoninterview": {"de": "Telefoninterview", "en": "Phone interview", "tone": "progress", "icon": "phone"}, "gespraech_digital": {"de": "Gespräch (digital)", "en": "Interview (video)", "tone": "progress", "icon": "globe"}, "gespraech_vor_ort": {"de": "Gespräch vor Ort", "en": "Interview (on site)", "tone": "progress", "icon": "map-pin"}, "einstellungstest": {"de": "Einstellungstest", "en": "Assessment", "tone": "progress", "icon": "graduation-cap"}, "vertrag_erhalten": {"de": "Vertrag erhalten", "en": "Contract received", "tone": "success", "icon": "file-text"}, "vertrag_unterzeichnet": {"de": "Vertrag unterzeichnet", "en": "Contract signed", "tone": "success", "icon": "pen-line"}, "angenommen": {"de": "Angenommen", "en": "Accepted", "tone": "success", "icon": "handshake"}, "probezeit_bestanden": {"de": "Probezeit bestanden", "en": "Probation passed", "tone": "success", "icon": "badge-check"}, "absage": {"de": "Absage", "en": "Rejected", "tone": "danger", "icon": "circle-x"}, "zurueckgezogen": {"de": "Zurückgezogen", "en": "Withdrawn", "tone": "neutral", "icon": "rotate-ccw"}, "keine_antwort": {"de": "Keine Antwort", "en": "No reply", "tone": "neutral", "icon": "hourglass"}};

